<script module>
  import { isSlot } from '../../utils'
  import Markdown from './Markdown.svelte'
  export const MarkdownSnippet = { block, inline }
</script>

<!-- Inline -->
{#snippet inline(content, useMarkdown = true)}
  {#if isSlot(content)}
    {@render content()}
  {:else if useMarkdown}
    <Markdown {content} inline />
  {:else}
    {content}
  {/if}
{/snippet}

<!-- Standard -->
{#snippet block(content, useMarkdown = true)}
  {#if isSlot(content)}
    {@render content()}
  {:else if useMarkdown}
    <Markdown {content} />
  {:else}
    {content}
  {/if}
{/snippet}
